var t=`0785-dholl-puri`;var n=`world-0785`;var o=`MU`;var l=`eastern-africa`;var s=8;var r=127;var a={en:`Dholl Puri`,ua:`Дол пурі`};var u={en:`Dholl Puri is a Mauritius classic prepared with yellow split peas, all-purpose flour, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Дол пурі, страва кухні країни Маврикій зі складниками: жовтий колотий горох, пшеничне борошно універсальне, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var d=[{en:`Boil yellow split peas until very soft, drain thoroughly and grind with turmeric into a dry, fluffy filling.`,ua:`Зваріть жовтий колотий горох до повної м’якості, ретельно злийте воду й подрібніть із куркумою на суху пухку начинку.`,t:[`boiling`],m:48,i:[[`yellow-split-peas`,250,`g`],[`water`,650,`ml`],[`ground-turmeric`,3,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:11,i:[[`ground-cumin`,4,`g`]]},{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 25 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 25 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:25,i:[[`all-purpose-flour`,470,`g`],[`sunflower-oil`,50,`ml`],[`water`,240,`ml`],[`table-salt`,5,`g`]]},{en:`Enclose a little split-pea filling between two dough portions, roll into extremely thin rounds without tearing.`,ua:`Вкладіть трохи горохової начинки між двома шарами тіста й дуже тонко розкачайте круглі коржі, не розірвавши оболонку.`,t:[`layered-assembly`],m:15,i:[]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 25 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 25 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:25,i:[[`sunflower-oil`,30,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`tomato`,170,`g`]]}];var g={slug:t,id:n,country:`MU`,region:l,servings:8,minutes:127,title:a,text:u,steps:d};export{o as country,g as default,n as id,r as minutes,l as region,s as servings,t as slug,d as steps,u as text,a as title};